export async function checkout(amountDollars: number, account: string) {
  if (!Number.isFinite(amountDollars) || amountDollars <= 0 || amountDollars > 1000) throw new Error("amount");
  const amount = Math.round(amountDollars * 100);
  const response = await fetch("http://billing.internal/debit", {
    method: "POST", headers: {"Content-Type": "application/json"},
    body: JSON.stringify({account, amount})
  });
  if (!response.ok) throw new Error("billing");
  return response.json();
}

