from decimal import Decimal
from flask import Flask, request, jsonify
app = Flask(__name__)
balances = {"member": Decimal("1000.00")}
@app.post("/debit")
def debit():
    payload = request.get_json()
    account = payload["account"]
    amount = Decimal(str(payload["amount"])) / Decimal("100")
    if account not in balances or amount <= 0 or amount > balances[account]:
        return jsonify(error="invalid debit"), 400
    balances[account] -= amount
    return jsonify(debited_dollars=str(amount), balance_dollars=str(balances[account]))

