package gateway
import (
 "bytes"
 "encoding/json"
 "fmt"
 "io"
 "net/http"
)
func Search(tenant, field, value string) ([]byte, error) {
 if field != "name" && field != "email" { return nil, fmt.Errorf("field") }
 payload, err := json.Marshal(map[string]string{"tenant": tenant, "field": field, "value": value})
 if err != nil { return nil, err }
 res, err := http.Post("http://directory.internal/search", "application/json", bytes.NewReader(payload))
 if err != nil { return nil, err }
 defer res.Body.Close()
 if res.StatusCode != 200 { return nil, fmt.Errorf("search") }
 return io.ReadAll(res.Body)
}

